selected.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for choice in combinations(ids, k):
        candidate = list(choice)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
